head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[input > M > setIgnoreChar]<br/>컴포넌트의 ignoreChar 속성을 설정합니다.",
    "validation" : [
        "ignoreChar(필수) 파라미터로 정규식의 문자클래스 형식으로 입력이 불가능한 문자 집합을 설정합니다.",
        "정규식의 문자클래스에서 특수문자로 처리되는 ']', '-', '\' 등의 문자는 이스케이프 처리하여 설정해야 합니다.",
        "설정값은 정규식의 문자클래스('[...]' 처리)에 반영되어 입력이 불가능한 문자를 찾는데 사용됩니다.",       
        "메소드로 ignoreChar 속성값 설정 시 입력된 값이 초기화됩니다.",
        "속성이 바인딩 되었을때 연결된 데이터도 초기화됩니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.get_text = function(target) {    
    let rtn = '';
    let tagName = target.render.tagName

    if (tagName !== "INPUT") {
        rtn = target.render.textContent
        wf_body_bottom.getObj("scwin").setReturnValue("text : " + rtn);    
    }
    else {
        rtn = target.render.value
        wf_body_bottom.getObj("scwin").setReturnValue("text : " + rtn);   
    }    
}

let strValue = "azAZ123가나다~!@#$%^&*()_+-=\[]{},./;':\""


// target1
scwin.btn_setValue1_onclick = function (e) {
    target1.setIgnoreChar("0-9");
    target1.setValue(strValue);
    target1.focus();
};

scwin.btn_getText1_onclick = function (e) {
    scwin.get_text(target1);
}

// target2
scwin.btn_setValue2_onclick = function (e) {
    target2.setIgnoreChar("a-z");
    target2.setValue(strValue);
    target2.focus();
};

scwin.btn_getText2_onclick = function (e) {
    scwin.get_text(target2);
}

// target3
scwin.btn_setValue3_onclick = function (e) {
    target3.setIgnoreChar("A-Z");
    target3.setValue(strValue);
    target3.focus();
};

scwin.btn_getText3_onclick = function (e) {
    scwin.get_text(target3);
};

// target4
scwin.btn_setValue4_onclick = function (e) {
    target4.setIgnoreChar("~!@#$%^&*()_+|\\\\\\-={}[\\]:\";\'<>?,./");    
    target4.setValue(strValue);
    target4.focus();
};

scwin.btn_getText4_onclick = function (e) {
    scwin.get_text(target4);
};

// target5
scwin.btn_setValue5_onclick = function (e) {
    target5.setIgnoreChar("a-z");    
    target5.focus();
};

scwin.btn_getText5_onclick = function (e) {
    scwin.get_text(target5);
};

// target6
scwin.btn_setValue6_onclick = function (e) {
    target6.setIgnoreChar("a-z_");    
    target6.focus();
};

scwin.btn_getText6_onclick = function (e) {
    scwin.get_text(target6);

    wf_body_bottom.getObj("scwin").setReturnValue("바인딩 data : " + gdm_ref.get("key1"));   
};



scwin.btn_setRef_onclick = function (e) {
    target6.setRef("data:gdm_ref.key1");
};
